          ["case_input", "string"]
        ]
      }
    },
    {
      "id": "2",
      "type": "llm",
      "param": {
        "system": "You are an expert Python programmer and code translator. Your task is to ensure the output is valid, executable Python code.",
        "user": "Analyze the following input. If it is code in a language other than Python, translate it to Python. If it is already Python code, check its content and format for correctness and fix any errors. Output ONLY the valid Python code. Do not include any explanations, markdown formatting (like ```python), or extra text.\n\nInput:\n{{#1.case_input#}}"
      }
    },
    {
      "id": "3",
      "type": "code",
      "param": {
        "variables": [
          ["code_str", ["text", "2"]]
        ],
        "outputs": [
          ["result", "string"]
        ],
        "code": "def main(code_str: str):\n\timport sys\n\tfrom io import StringIO\n\t\n\t# Save the original stdout\n\toriginal_stdout = sys.stdout\n\t\n\t# Redirect stdout to capture print statements\n\tsys.stdout = StringIO()\n\t\n\ttry:\n\t\t# Execute the Python code\n\t\texec(code_str)\n\t\t# Get the output from the redirected stdout\n\t\toutput = sys.stdout.getvalue()\n\texcept Exception as e:\n\t\t# Capture any execution errors\n\t\toutput = str(e)\n\tfinally:\n\t\t# Restore the original stdout\n\t\tsys.stdout = original_stdout\n\t\n\treturn {\n\t\t\"result\": output\n\t}"
      }
    },
    {
      "id": "4",
      "type": "end",
      "param": {
        "outputs": [
          ["python_code", ["text", "2"]],
          ["result", ["result", "3"]]
        ]
      }
    }
  ],
