import urllib.error

def main(url: str):
    # Parse the GitHub URL to extract owner and repo
    # Expected format: https://github.com/owner/repo
    try:
        clean_url = url.strip().strip('/')
        parts = clean_url.split('/')
        if 'github.com' not in parts:
            return {"file_structure": json.dumps({"error": "Invalid GitHub URL provided"})}

        repo_index = parts.index('github.com') + 1
        if len(parts) < repo_index + 2:
             return {"file_structure": json.dumps({"error": "Invalid GitHub URL format"})}

        owner = parts[repo_index]
        repo = parts[repo_index + 1]
    except Exception as e:
        return {"file_structure": json.dumps({"error": f"URL parsing error: {str(e)}"})}

    base_api = f"https://api.github.com/repos/{owner}/{repo}/contents"
    headers = {'User-Agent': 'Dify-Workflow-GitHub-Parser'}

    def fetch_contents(path):
        api_url = f"{base_api}{path}"
        try:
            req = urllib.request.Request(api_url, headers=headers)
            with urllib.request.urlopen(req, timeout=10) as response:
                data = json.loads(response.read().decode('utf-8'))
        except urllib.error.HTTPError as e:
            return {"error": f"HTTP Error {e.code}: {e.reason}"}
        except Exception as e:
            return {"error": str(e)}

        # If the response is a single file (not a list)
        if isinstance(data, dict):
            if data.get('type') == 'file':
                return {
                    'name': data.get('name'),
                    'type': 'file',
                    'path': data.get('path'),
                    'size': data.get('size')
                }
            return data # Should not happen for root, but handle anyway

        # If the response is a list (directory contents)
        if isinstance(data, list):
            structure = []
            for item in data:
                if item.get('type') == 'file':
                    structure.append({
                        'name': item.get('name'),
                        'type': 'file',
                        'path': item.get('path'),
                        'size': item.get('size')
                    })
                elif item.get('type') == 'dir':
                    # Recursive call for subdirectories
                    children = fetch_contents(item.get('path'))
                    structure.append({
                        'name': item.get('name'),
                        'type': 'dir',
                        'path': item.get('path'),
                        'children': children
                    })
            return structure

        return {}

    # Start fetching from root
    result_tree = fetch_contents("")
    return {
        "file_structure": json.dumps(result_tree, indent=2, ensure_ascii=False)
