        return {"file_structure": f"Error: Parsing failed - {str(e)}", "readme_content": ""}

    base_api = f"https://api.github.com/repos/{owner}/{repo}/contents"
    readme_api = f"https://api.github.com/repos/{owner}/{repo}/readme"
    headers = {'User-Agent': 'Dify-Workflow-GitHub-Parser'}

    # 1. Fetch README Content
    readme_text = ""
    try:
        req = urllib.request.Request(readme_api, headers=headers)
        with urllib.request.urlopen(req, timeout=10) as response:
            data = json.loads(response.read().decode('utf-8'))
            # GitHub API returns content in base64
            readme_text = base64.b64decode(data.get('content', '')).decode('utf-8')
    except urllib.error.HTTPError as e:
        if e.code == 404:
            readme_text = "No README file found in the repository."
        else:
            readme_text = f"Error fetching README: HTTP {e.code}"
    except Exception as e:
        readme_text = f"Error fetching README: {str(e)}"

    # 2. Fetch File Structure (Recursive)
    def fetch_contents(path):
        api_url = f"{base_api}{path}"
        try:
            req = urllib.request.Request(api_url, headers=headers)
            with urllib.request.urlopen(req, timeout=10) as response:
                data = json.loads(response.read().decode('utf-8'))
        except urllib.error.HTTPError as e:
            return {"error": f"HTTP Error {e.code}"}
        except Exception as e:
            return {"error": str(e)}

        if isinstance(data, dict):
            if data.get('type') == 'file':
                return {'name': data.get('name'), 'type': 'file'}
            return data 

        if isinstance(data, list):
            structure = []
            for item in data:
                if item.get('type') == 'file':
                    structure.append({'name': item.get('name'), 'type': 'file'})
                elif item.get('type') == 'dir':
                    children = fetch_contents(item.get('path'))
                    if isinstance(children, dict) and 'error' in children:
                        structure.append({'name': item.get('name'), 'type': 'dir', 'error': children['error']})
                    else:
                        structure.append({'name': item.get('name'), 'type': 'dir', 'children': children})
            return structure
        return {}

    def build_tree(items, prefix=""):
        output_lines = []
        for i, item in enumerate(items):
            is_last = i == len(items) - 1
            connector = "└── " if is_last else "├── "
            output_lines.append(f"{prefix}{connector}{item['name']}")

            if item.get('type') == 'dir' and item.get('children'):
                extension = "    " if is_last else "│   "
                output_lines.append(build_tree(item['children'], prefix + extension))
        return "\n".join(output_lines)

    result_tree = fetch_contents("")

    if isinstance(result_tree, dict) and 'error' in result_tree:
        return {"file_structure": result_tree['error'], "readme_content": readme_text}

    return {
        "file_structure": build_tree(result_tree),
        "readme_content": readme_text
    }"
      }
